const body = $input.first().json.body || {};
const messages = body.messages;
const allowedRoles = new Set(['system', 'user', 'assistant']);

function invalid(error) {
  return [{ json: { ok: false, statusCode: 400, error } }];
}

if (!Array.isArray(messages) || messages.length < 1 || messages.length > 50) {
  return invalid('messages must contain between 1 and 50 entries.');
}
if (body.stream === true) {
  return invalid('streaming is not supported by this workflow endpoint.');
}

let totalCharacters = 0;
const cleanMessages = [];
for (const message of messages) {
  if (!message || typeof message !== 'object' || Array.isArray(message)) {
    return invalid('every message must be an object.');
  }
  if (!allowedRoles.has(message.role)) {
    return invalid(`unsupported message role: ${String(message.role)}`);
  }
  if (typeof message.content !== 'string' || !message.content.trim()) {
    return invalid('every message must contain non-empty text content.');
  }
  if (message.content.length > 16000) {
    return invalid('a message exceeds the 16000-character limit.');
  }
  totalCharacters += message.content.length;
  if (totalCharacters > 32000) {
    return invalid('message content exceeds the 32000-character request limit.');
  }
  cleanMessages.push({ role: message.role, content: message.content });
}

const model = String(body.model || 'local-model').trim();
if (!model || model.length > 200) {
  return invalid('model must contain between 1 and 200 characters.');
}
const temperature = body.temperature ?? 0.7;
if (typeof temperature !== 'number' || !Number.isFinite(temperature) || temperature < 0 || temperature > 2) {
  return invalid('temperature must be a number between 0 and 2.');
}
const maxTokens = body.max_tokens ?? 512;
if (!Number.isInteger(maxTokens) || maxTokens < 1 || maxTokens > 4096) {
  return invalid('max_tokens must be an integer between 1 and 4096.');
}

return [{ json: {
  ok: true,
  statusCode: 200,
  model,
  messages: cleanMessages,
  temperature,
  max_tokens: maxTokens,
} }];

const response = $input.first().json || {};
const request = $('Validate Chat Request').first().json;
const choice = Array.isArray(response.choices) ? response.choices[0] : null;
const content = choice?.message?.content;

if (typeof content !== 'string' || !content.trim()) {
  return [{ json: {
    ok: false,
    statusCode: 502,
    error: 'llama-server returned no assistant message.',
  } }];
}

const tokenCount = (value) => Number.isInteger(value) && value >= 0 ? value : null;
const usage = response.usage && typeof response.usage === 'object'
  ? {
      prompt_tokens: tokenCount(response.usage.prompt_tokens),
      completion_tokens: tokenCount(response.usage.completion_tokens),
      total_tokens: tokenCount(response.usage.total_tokens),
    }
  : null;

return [{ json: {
  ok: true,
  statusCode: 200,
  completion: {
    id: typeof response.id === 'string' ? response.id : `chatcmpl-${Date.now()}`,
    object: 'chat.completion',
    created: Number.isInteger(response.created) ? response.created : Math.floor(Date.now() / 1000),
    model: typeof response.model === 'string' ? response.model : request.model,
    choices: [{
      index: Number.isInteger(choice.index) ? choice.index : 0,
      message: { role: 'assistant', content },
      finish_reason: typeof choice.finish_reason === 'string' ? choice.finish_reason : null,
    }],
    usage,
  },
} }];
